"""A Class for performing sequenced interactions to map structures in the Monaco application"""
from interops.libraries.common.state import State
from interops.libraries.monaco.interactions.objects.monaco_map_structures_objects import MonacoMapStructuresObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.monaco.interactions import MonacoDashboard

class MapStructures:
    """
    Page Object Class for the  Map Structures dialog used for map structures in template to the corresponding ones
    in RT structure set of the patient data.
    """
    def __init__(self) -> None:
        CommonActions.wait_for_object_exists(MonacoMapStructuresObjects.map_Structures_Dialog)
        self.remove_from_imrt_constraints = State(MonacoMapStructuresObjects.imrt_Constraints_Button)
        self.remove_from_dosimetric_criteria = State(MonacoMapStructuresObjects.dosimetric_Criteria_Button)
        self.change_structure_name =  State(MonacoMapStructuresObjects.change_Structure_Name_Button)

    def map_structure(self, map_mapchine_column:int, from_structure:str, to_structure:str):
        """
        Map structure from a structure to another name.

        :params: map_mapchine_column (int), the index of Map Machine column
                from_structure (str), the structure in template to be mapped
                to_structure (str), the mapping structure in the list
        """
        from_structure_obj = CommonActions.find_object({"text": from_structure, "type":"ListViewItem"})
        row = getattr( from_structure_obj, "row", 0)
        mapping_combobox =  {"id":f"{map_mapchine_column} - {row}", "type": "ComboBox"}
        arrow_button = {"container": mapping_combobox, "type":"Button"}
        CommonActions.click_button(arrow_button)
        MonacoMapStructuresObjects.o_ListItem["text"] = to_structure
        target = CommonActions.find_any_object([MonacoMapStructuresObjects.o_ListItem])
        if target:
            CommonActions.mouse_click(CommonActions.get_global_bounds(target))
        else:
            print("Unable to locate the mapping structure")

    def click_ok(self, overwriteIfExist:bool = True):
        """
        Click OK button on the mapping structure dialog

        :param: overwriteIfExist (bool), if to overwrite.
        """
        CommonActions.click_button(MonacoMapStructuresObjects.oK_Button)
        MonacoDashboard.confirm_notification(overwriteIfExist)
